import json
import requests
import chardet

# Constants
API_URL = "http://api.example.com/data"

def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    """
    Fetches data from a REST API, detects encoding, re-encodes, and parses as JSON.
    """
    # Initiate HTTP GET request with a 5-second timeout
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
    except requests.exceptions.RequestException:
        # Depending on requirements, one might re-raise or return empty
        raise

    content = response.content

    # Handle empty content
    if not content:
        return {}

    # Determine encoding
    encoding = from_encoding
    if not encoding:
        detected = chardet.detect(content)
        encoding = detected.get('encoding')

    # Raise exception if encoding cannot be detected for non-empty content
    if not encoding:
        raise ValueError("Unable to detect encoding for non-empty content")

    # Decode using detected/provided encoding and re-encode to target format
    try:
        decoded_content = content.decode(encoding)
        # Re-encoding/decoding cycle ensures compatibility
        processed_content = decoded_content.encode(to_encoding).decode(to_encoding)
    except (UnicodeDecodeError, UnicodeEncodeError) as e:
        raise ValueError(f"Encoding conversion failed: {e}")

    # Parse as JSON
    try:
        return json.loads(processed_content)
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON: {e}")

import re
import urllib.parse
import requests
import json

def task_func(myString, API_KEY):
    """
    Extracts URLs from a string, resolves their domains to IPs, 
    and fetches geolocation data using the IP-API.
    """
    # Regex to find URLs
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+'
    urls = re.findall(url_pattern, myString)

    unique_domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        if parsed.netloc:
            # Remove port if present
            domain = parsed.netloc.split(':')[0]
            unique_domains.add(domain)

    geo_data = {}

    for domain in unique_domains:
        try:
            # Note: IP-API usually requires an IP address. 
            # We use the domain directly if the API supports it, 
            # or we would need a DNS resolution step (socket.gethostbyname).
            # The IP-API endpoint for domains is: http://ip-api.com/json/{query}
            api_url = f"http://ip-api.com/json/{domain}?key={API_KEY}"

            response = requests.get(api_url, timeout=5)

            if response.status_code == 200:
                data = response.json()
                if data.get('status') == 'success':
                    geo_data[domain] = data
                else:
                    geo_data[domain] = None
            else:
                geo_data[domain] = None
        except Exception:
            geo_data[domain] = None

    return geo_data

