import re
import urllib.parse
import requests
import json

def task_func(myString, API_KEY):
    """
    Extracts all URLs from the string, resolves the domain to an IP address,
    and fetches geolocation data using the ip-api service.
    """
    # Regex to extract URLs
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+'
    urls = re.findall(url_pattern, myString)

    unique_domains = set()
    for url in urls:
        # Parse the domain from the URL
        domain = urllib.parse.urlparse(url).netloc
        # Remove port if present
        domain = domain.split(':')[0]
        if domain:
            unique_domains.add(domain)

    results = {}

    for domain in unique_domains:
        try:
            # ip-api requires an IP address or a domain. 
            # Note: The free tier of ip-api supports domain lookups directly.
            # Using the JSON endpoint: http://ip-api.com/json/{query}
            api_url = f"http://ip-api.com/json/{domain}?key={API_KEY}"
            response = requests.get(api_url, timeout=5)

            if response.status_code == 200:
                data = response.json()
                # Check if the API returned a successful result
                if data.get('status') == 'success':
                    results[domain] = data
                else:
                    results[domain] = None
            else:
                results[domain] = None
        except Exception:
            results[domain] = None

    return results

