def task_func(directory_path: str) -> dict:
    """
    Counts the total appearances of all keys in all JSON files in the specified directory.

    Args:
        directory_path (str): The path to the directory containing JSON files.

    Returns:
        dict: A dictionary with the keys from the JSON files as keys and their counts as values.
    """
    key_counts = collections.Counter()

    def count_keys(data):
        """Recursively traverse the JSON structure to count keys."""
        if isinstance(data, dict):
            for key, value in data.items():
                key_counts[key] += 1
                count_keys(value)
        elif isinstance(data, list):
            for item in data:
                count_keys(item)

    # Iterate through files in the directory
    if not os.path.exists(directory_path):
        return {}

    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    count_keys(data)
            except (json.JSONDecodeError, IOError):
                # Skip files that are not valid JSON or cannot be read
                continue

    return dict(key_counts)
