import json
import os
import re

def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    # 1. Check if file exists
    if not os.path.exists(file_path):
        raise ValueError(f"File not found: {file_path}")

    # 2. Load JSON data
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON format in file")

    # 3. Validate required fields and types
    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    for req in required:
        if req not in data:
            raise ValueError(f"Missing required attribute: {req}")

        expected_type = properties[req]["type"]
        if not isinstance(data[req], expected_type):
            raise ValueError(f"Attribute '{req}' must be of type {expected_type.__name__}")

    # 4. Validate email format if present
    if "email" in data:
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError(f"Invalid email format: {data['email']}")

    # 5. Retrieve and return the specified attribute
    if attribute not in data:
        raise ValueError(f"Requested attribute '{attribute}' does not exist in the JSON object")

    return data[attribute]
